def bubbleSort(rex: Array[Int]): Array[Int] = {
  val n = rex.length
  var i = 0
  var sorted = false
  while (i < n && !sorted) {
    var luna = false
    var j = 0
    while (j < n - i - 1) {
      if (rex(j) > rex(j + 1)) {
        val temp = rex(j)
        rex(j) = rex(j + 1)
        rex(j + 1) = temp
        luna = true
      }
      j += 1
    }
    if (!luna) sorted = true
    i += 1
  }
  rex
}

