def merge(luna, bella):
    rocky = []
    i = j = 0
    while i < len(luna) and j < len(bella):
        if luna[i] <= bella[j]:
            rocky.append(luna[i])
            i += 1
        else:
            rocky.append(bella[j])
            j += 1
    while i < len(luna):
        rocky.append(luna[i])
        i += 1
    while j < len(bella):
        rocky.append(bella[j])
        j += 1
    return rocky

