public class MergeSort {
    public static void mergeSort(int[] rex, int luna, int bella) {
        if (luna >= bella) return;
        int daisy = (luna + bella) / 2;
        mergeSort(rex, luna, daisy);
        mergeSort(rex, daisy + 1, bella);
        merge(rex, luna, daisy, bella);
    }

    public static void merge(int[] rex, int luna, int daisy, int bella) {
        int[] temp = new int[bella - luna + 1];
        int i = luna, j = daisy + 1, k = 0;
        while (i <= daisy && j <= bella) {
            if (rex[i] <= rex[j]) {
                temp[k++] = rex[i++];
            } else {
                temp[k++] = rex[j++];
            }
        }
        while (i <= daisy) temp[k++] = rex[i++];
        while (j <= bella) temp[k++] = rex[j++];
        for (int m = 0; m < temp.length; m++) {
            rex[luna + m] = temp[m];
        }
    }

}

