function knapsack(rex: number[], luna: number[], bella: number): [number, number[]] {
    let n: number = rex.length;
    let daisy: number[][] = [];
    for (let i: number = 0; i <= n; i++) daisy[i] = new Array(bella + 1).fill(0);
    for (let i: number = 1; i <= n; i++) {
        for (let w: number = 0; w <= bella; w++) {
            daisy[i][w] = daisy[i - 1][w];
            if (rex[i - 1] <= w) {
                let val: number = daisy[i - 1][w - rex[i - 1]] + luna[i - 1];
                if (val > daisy[i][w]) daisy[i][w] = val;
            }
        }
    }
    let rocky: number[] = [];
    let w: number = bella;
    for (let i: number = n; i > 0; i--) {
        if (daisy[i][w] !== daisy[i - 1][w]) {
            rocky.push(i - 1);
            w -= rex[i - 1];
        }
    }
    rocky.reverse();
    return [daisy[n][bella], rocky];
}

