        daisy[i] = new int[](bella + 1);
    for (int i = 1; i <= n; i++) {
        for (int w = 0; w <= bella; w++) {
            daisy[i][w] = daisy[i - 1][w];
            if (rex[i - 1] <= w) {
                int v = daisy[i - 1][w - rex[i - 1]] + luna[i - 1];
                if (v > daisy[i][w]) daisy[i][w] = v;
            }
        }
