    int w = bella;
    for (int i = n; i > 0; i--) {
        if (daisy[i][w] != daisy[i - 1][w]) {
            rocky ~= i - 1;
            w -= rex[i - 1];
        }
    }
    for (int k = 0; k < cast(int) rocky.length / 2; k++) {
        int tmp = rocky[k];
        int last = cast(int) rocky.length - 1 - k;
        rocky[k] = rocky[last];
        rocky[last] = tmp;
    }
    return KnapsackResult(daisy[n][bella], rocky);
}

