def build_lps(rex):
    bella = [0] * len(rex)
    length = 0
    i = 1
    while i < len(rex):
        if rex[i] == rex[length]:
            length += 1
            bella[i] = length
            i += 1
        else:
            if length != 0:
                length = bella[length - 1]
            else:
                bella[i] = 0
                i += 1
    return bella

def kmp_search(luna, rex):
    bella = build_lps(rex)
    daisy = []
    i = 0
    j = 0
    while i < len(luna):
        if luna[i] == rex[j]:
            i += 1
            j += 1
        if j == len(rex):
            daisy.append(i - j)
            j = bella[j - 1]
        elif i < len(luna) and luna[i] != rex[j]:
            if j != 0:
                j = bella[j - 1]
            else:
                i += 1
    return daisy

